(() => {
  const canvasBox = document.getElementById('hdr-canvas-box');
  const canvas = document.getElementById('hdr-pattern-canvas');
  const ctx = canvas.getContext('2d');
  const patternSelect = document.getElementById('hdr-pattern-select');
  const patternLabel = document.getElementById('hdr-pattern-label');
  const fsBtn = document.getElementById('hdr-fs-btn');

  function resize() {
    const rect = canvasBox.getBoundingClientRect();
    canvas.width = rect.width * (window.devicePixelRatio || 1);
    canvas.height = rect.height * (window.devicePixelRatio || 1);
    render();
  }
  window.addEventListener('resize', resize);

  function render() {
    const p = patternSelect.value;
    const w = canvas.width;
    const h = canvas.height;

    ctx.clearRect(0, 0, w, h);

    if (p === 'gradient') {
      patternLabel.textContent = '10-Bit Grayscale Gradient Sweep';
      const grad = ctx.createLinearGradient(0, 0, w, 0);
      grad.addColorStop(0, '#000000');
      grad.addColorStop(1, '#ffffff');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, w, h);
    } else if (p === 'oled5') {
      patternLabel.textContent = '5% Near-Black OLED Uniformity Field';
      ctx.fillStyle = '#0d0d0d'; // 5% of 255 ~= 13 (#0d0d0d)
      ctx.fillRect(0, 0, w, h);
    } else if (p === 'oled10') {
      patternLabel.textContent = '10% Gray Field';
      ctx.fillStyle = '#1a1a1a'; // 10% of 255 ~= 26 (#1a1a1a)
      ctx.fillRect(0, 0, w, h);
    } else if (p === 'starfield') {
      patternLabel.textContent = 'Mini-LED Blooming Starfield';
      ctx.fillStyle = '#000000';
      ctx.fillRect(0, 0, w, h);

      // Generate high contrast stars
      const stars = [
        { x: w * 0.2, y: h * 0.3, r: 6 },
        { x: w * 0.5, y: h * 0.5, r: 12 },
        { x: w * 0.8, y: h * 0.4, r: 8 },
        { x: w * 0.35, y: h * 0.75, r: 5 },
        { x: w * 0.7, y: h * 0.8, r: 7 },
      ];
      ctx.fillStyle = '#ffffff';
      for (const s of stars) {
        ctx.beginPath();
        ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (p === 'clipping') {
      patternLabel.textContent = 'Peak White Highlight Clipping Steps';
      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, w, h);

      const steps = [
        { label: '900 Nits', color: '#e6e6e6' },
        { label: '1000 Nits', color: '#eeeeee' },
        { label: '2000 Nits', color: '#f7f7f7' },
        { label: '4000 Nits', color: '#ffffff' },
      ];
      const blockW = w / 4;
      steps.forEach((s, idx) => {
        ctx.fillStyle = s.color;
        ctx.fillRect(idx * blockW + 10, h * 0.2, blockW - 20, h * 0.6);
        ctx.fillStyle = '#000000';
        ctx.font = 'bold ' + (14 * (window.devicePixelRatio || 1)) + 'px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(s.label, idx * blockW + blockW / 2, h * 0.5);
      });
    } else if (p === 'colorbars') {
      patternLabel.textContent = 'SMPTE Standard Color Bars';
      const colors = ['#ffffff', '#ffff00', '#00ffff', '#00ff00', '#ff00ff', '#ff0000', '#0000ff'];
      const barW = w / colors.length;
      colors.forEach((c, idx) => {
        ctx.fillStyle = c;
        ctx.fillRect(idx * barW, 0, barW, h);
      });
    }
  }

  patternSelect.addEventListener('change', render);

  function toggleFullscreen() {
    if (!document.fullscreenElement) {
      canvasBox.requestFullscreen().catch(() => {});
    } else {
      document.exitFullscreen().catch(() => {});
    }
  }

  fsBtn.addEventListener('click', toggleFullscreen);
  canvas.addEventListener('click', toggleFullscreen);

  document.addEventListener('fullscreenchange', () => {
    setTimeout(resize, 100);
  });

  resize();
})();
